let locale = "en";
export function setLocale(value: string | undefined): void {
  const candidate = (value || "en").replace(/_/g, "-");
  const match = hostLocales.find(code => code.toLowerCase() === candidate.toLowerCase());
  locale = match ?? (candidate.toLowerCase().startsWith("zh-hant") ? "zh-TW" : candidate.toLowerCase().startsWith("zh-hans") ? "zh-CN" : candidate.split("-")[0]);
  if (!hostLocales.some(code => code.toLowerCase() === locale.toLowerCase())) locale = "en";
}
export function isRtl(): boolean { return locale === "ar"; }
export function localize(key: string): string { return catalogs[locale]?.[key] ?? catalogs.en[key] ?? key; }
export function format(key: string, values: Record<string, string | number>): string {
  return localize(key).replace(/\{([a-zA-Z]+)\}/g, (whole, name: string) => Object.hasOwn(values, name) ? String(values[name]) : whole);
}
